                    a, b = a - dr, b - dc
                z, q = r + dr, c + dc
                while (z + dr, q + dc) in pts:
                    z, q = z + dr, q + dc

                # A different-colored adjacent marker at an endpoint
                # indicates that the stroke extends away from that marker.
                def marked(rr, cc):
                    return (0 <= rr < h and 0 <= cc < w
                            and grid[rr][cc] not in (bg, color))

                extend_a = not marked(a + dr, b + dc)
                extend_z = not marked(z - dr, q - dc)
                if extend_a:
